import{_ as i,c as t,o as a,ag as l}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"TAAW Review","description":"","frontmatter":{"title":"TAAW Review"},"headers":[],"relativePath":"general/taaw-review.md","filePath":"general/taaw-review.md","lastUpdated":null}'),o={name:"general/taaw-review.md"};function r(n,e,s,c,h,u){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="taaw-review" tabindex="-1">TAAW Review <a class="header-anchor" href="#taaw-review" aria-label="Permalink to &quot;TAAW Review&quot;">​</a></h1><h2 id="enclosure-2-taaw-review-workflow" tabindex="-1">Enclosure 2 TAAW Review: Workflow <a class="header-anchor" href="#enclosure-2-taaw-review-workflow" aria-label="Permalink to &quot;Enclosure 2 TAAW Review: Workflow&quot;">​</a></h2><p><strong>Purpose</strong>: To reduce variance, improve efficiency, expand continuity and interoperability, increase transparency, and allow for systemic adjustments to the review.</p><p><strong>NOTE</strong>: (comments)</p><ul><li><p>Comment bubbles should highlight the general area to which the comment belongs.</p></li><li><p>Be as specific as possible with comments.</p></li><li><p>If a required change is based on Policy, Authorities, or J39 Guidance, add the following to the start of the comment:</p><ul><li><strong>REQUIRED CHANGE</strong>:</li><li>All other comments will be seen as recommendations.</li></ul></li></ul><p>NOTE TO TEAMS: Wait until the comments are complete before modifying the TAAW. These comments are not verified through the OPCEN, and changes to the documents and resolving or deleting comments will delay the support provided.</p><h3 id="broad-steps" tabindex="-1">Broad Steps: <a class="header-anchor" href="#broad-steps" aria-label="Permalink to &quot;Broad Steps:&quot;">​</a></h3><h2 id="ensure-task-is-in-the-opcen-rfs-tracker" tabindex="-1">Ensure Task is in the OPCEN RFS Tracker. <a class="header-anchor" href="#ensure-task-is-in-the-opcen-rfs-tracker" aria-label="Permalink to &quot;Ensure Task is in the OPCEN RFS Tracker.&quot;">​</a></h2><h2 id="upload-enclosure-to-sipr-portal" tabindex="-1">Upload Enclosure to SIPR Portal. <a class="header-anchor" href="#upload-enclosure-to-sipr-portal" aria-label="Permalink to &quot;Upload Enclosure to SIPR Portal.&quot;">​</a></h2><ul><li>Name file: <em>SERIES NAME_ENC 2_Date_Comments (EX. SERIES NAME_ENC 1_202406_Comments)</em>.</li></ul><h2 id="review-past-guidance" tabindex="-1">Review past guidance. <a class="header-anchor" href="#review-past-guidance" aria-label="Permalink to &quot;Review past guidance.&quot;">​</a></h2><h2 id="initial-contact-with-the-team" tabindex="-1">Initial contact with the team. <a class="header-anchor" href="#initial-contact-with-the-team" aria-label="Permalink to &quot;Initial contact with the team.&quot;">​</a></h2><h2 id="read-enclosure" tabindex="-1">Read Enclosure. <a class="header-anchor" href="#read-enclosure" aria-label="Permalink to &quot;Read Enclosure.&quot;">​</a></h2><h2 id="review-and-validate-with-comments" tabindex="-1">Review and validate with comments. <a class="header-anchor" href="#review-and-validate-with-comments" aria-label="Permalink to &quot;Review and validate with comments.&quot;">​</a></h2><h2 id="contact-the-team-rfis-in-depth-deconflict" tabindex="-1">Contact the team (RFIs, in-depth, deconflict). <a class="header-anchor" href="#contact-the-team-rfis-in-depth-deconflict" aria-label="Permalink to &quot;Contact the team (RFIs, in-depth, deconflict).&quot;">​</a></h2><h2 id="confirm-attributes-with-comments" tabindex="-1">Confirm attributes with comments. <a class="header-anchor" href="#confirm-attributes-with-comments" aria-label="Permalink to &quot;Confirm attributes with comments.&quot;">​</a></h2><h2 id="confirm-formatting" tabindex="-1">Confirm formatting. <a class="header-anchor" href="#confirm-formatting" aria-label="Permalink to &quot;Confirm formatting.&quot;">​</a></h2><h2 id="copy-enclosure-to-the-same-location" tabindex="-1">Copy Enclosure to the same location: <a class="header-anchor" href="#copy-enclosure-to-the-same-location" aria-label="Permalink to &quot;Copy Enclosure to the same location:&quot;">​</a></h2><ul><li>Name file: <em>SERIES NAME_ENC 2_Date_Comments (EX. SERIES NAME_ENC 1_202406_Comments)</em>.</li></ul><h2 id="apply-corrections-and-recommendations" tabindex="-1">Apply corrections and recommendations. <a class="header-anchor" href="#apply-corrections-and-recommendations" aria-label="Permalink to &quot;Apply corrections and recommendations.&quot;">​</a></h2><h2 id="submit-for-review-bluf-must-include-required-changes" tabindex="-1">Submit for review (BLUF must include REQUIRED changes): <a class="header-anchor" href="#submit-for-review-bluf-must-include-required-changes" aria-label="Permalink to &quot;Submit for review (BLUF must include REQUIRED changes):&quot;">​</a></h2><ul><li><p>OPCEN Leadership.</p></li><li><p>Company Leadership.</p></li></ul><h2 id="leadership-will-return-to-the-team" tabindex="-1">Leadership will return to the team. <a class="header-anchor" href="#leadership-will-return-to-the-team" aria-label="Permalink to &quot;Leadership will return to the team.&quot;">​</a></h2><h3 id="steps-taken-for-enclosure-2-review" tabindex="-1">Steps Taken for Enclosure 2 Review: <a class="header-anchor" href="#steps-taken-for-enclosure-2-review" aria-label="Permalink to &quot;Steps Taken for Enclosure 2 Review:&quot;">​</a></h3><ol><li><strong>Ensure that the task is in the RFS Tracker</strong>: [* If the task is not in the RFS Tracker, add it and appropriately include the requester&#39;s email and team.</li></ol><ul><li>When it is on the RFS tracker, assign yourself and change the status of the RFS to &quot;IN PROGRESS&quot; as you work on it.</li></ul><h2 id="upload-enclosure-to-sipr-portal-1" tabindex="-1">Upload Enclosure to SIPR Portal. <a class="header-anchor" href="#upload-enclosure-to-sipr-portal-1" aria-label="Permalink to &quot;Upload Enclosure to SIPR Portal.&quot;">​</a></h2><ul><li><p>Create a directory in Country Directory:</p><ul><li>Directory should be: SERIES-NAME-YYYY-MM.</li></ul></li><li><p>Name file: <em>CTRY-Series_Name-Comments</em>.</p></li><li><p>Add a link to working directory in Chatsurfer (SIPR).</p></li><li><p>Leave the original copy in the appropriate enclosure folder and create a &quot;comments&quot; version in the working folder.</p></li></ul><h2 id="review-past-guidance-from-the-j39-about-enclosure-2" tabindex="-1">Review past guidance from the J39 about Enclosure 2. <a class="header-anchor" href="#review-past-guidance-from-the-j39-about-enclosure-2" aria-label="Permalink to &quot;Review past guidance from the J39 about Enclosure 2.&quot;">​</a></h2><ul><li><p>Review PSYOP Kneeboard (SIPR): <code>https://YOURTSOC.smil.mil/sites/Ops/JED/J39/Kneeboards/</code></p><ul><li>Find the most current.</li><li>Review the intent of series groups.</li></ul></li><li><p>Review Objectives and Effects (SIPR): <code>https://YOURTSOC.smil.mil/sites/j5/SOFAssessments/</code></p></li><li><p>SMO / Desired Behavior and assessment criteria:</p><ul><li>From Enclosure 1.</li><li>Lined up on the Hierarchy of Psychological Effects Model (HPEM) (TM 3-53.11 Chapter 2).</li></ul></li><li><p>Portion markings are not over/under classified or missing.</p></li></ul><ol><li><strong>Contact team for initial communications</strong>.</li></ol><ul><li><p>Send Email to PSY-T, CC PSY-D Leadership and FUOPS Leadership.</p></li><li><p>Goal is to set up a communication channel for future discussion and to clarify who is working on the RFS and who is the customer of the RFS.</p></li></ul><ol><li><strong>Read</strong> entire Enclosure 2.</li></ol><ul><li><p>Ensure ENC 2 information still matches ENC 1.</p></li><li><p>Review header slide for correct series name and team information.</p></li><li><p>Write questions.</p></li><li><p>Don&#39;t make any corrections or recommendations yet.</p></li><li><p>Ensure research encompasses the full spectrum of classification sources.</p></li><li><p>Conduct TS level research.</p><ul><li>Conduct a general search of significant terms that neither confirm nor deny the TAAW&#39;s claims.</li><li>Pass down S//NF and lower information via Chatsurfer.</li><li>Put all findings on an accessory Word document to accompany TAAW.</li><li>If research grossly conflicts with TAAW and sufficient evidence in TAAW to back claims is not provided, return to Team for revision.</li></ul></li></ul><h2 id="review-attributes" tabindex="-1">Review Attributes. <a class="header-anchor" href="#review-attributes" aria-label="Permalink to &quot;Review Attributes.&quot;">​</a></h2><ul><li><ol><li>Refined Target Audience:</li></ol><ul><li>Confirm that the target audience (TA) is accurately categorized and refined beyond the Potential Target Audience List (PTAL).</li><li>Ensure the TA has been refined from Enc1. If the refined TA is the same as the unrefined TA, then contact the team to ensure the refinement process was completed.</li><li>Questions to Ask: <ul><li>Does this TA have a direct or indirect role in achieving the Supporting Psychological Objective (SPO)?</li><li>Is the TA defined sufficiently with clear attributes (e.g., organization, geographic region, occupation)?</li><li>What information exists on TS concerning the TA?</li></ul></li></ul></li><li><ol start="2"><li>Achievability:</li></ol><ul><li>Verify the achievability rating using control, barriers, and effect size.</li><li>Ensure barriers have been identified, and the TA has sufficient perceived and actual control over behavior.</li><li>Questions to Ask: <ul><li>Does the TA have the control and capability to achieve the SPO?</li><li>Are barriers to achieving the behavior realistic, and can they be addressed?</li><li>Does TS information reveal past attempts on the TA&#39;s part toward the desired behavior?</li></ul></li></ul></li><li><ol start="3"><li>Conditions (Cause-and-Effect Analysis):</li></ol><ul><li>Review cause and effect and have internal/external conditions described in detail.</li><li>Ensure sources are cited and internal assumptions are labeled clearly.</li><li>Questions to Ask: <ul><li>Are all relevant internal and external factors influencing behavior included in the analysis?</li><li>Is the behavior accurately defined, and are the causes and effects logical?</li></ul></li></ul></li><li><ol start="4"><li>Vulnerability:</li></ol><ul><li>Ensure the presence of HPEM analysis for where TA falls concerning SMO/DB.</li><li>Identify vulnerabilities that could be exploited to influence behavior.</li><li>Confirm that vulnerabilities encompass unmet needs, societal pressures, or other exploitable attributes.</li><li>Questions to Ask: <ul><li>Are all vulnerabilities, including unmet needs and societal norms, considered?</li><li>Is it feasible to address these vulnerabilities through psychological actions?</li></ul></li></ul></li><li><ol start="5"><li>Susceptibility:</li></ol><ul><li>Review susceptibility ratings, considering TA trust in channels, communication frequency, and existing beliefs.</li><li>Questions to Ask: <ul><li>Is this TA inclined to respond to influence activities based on its beliefs, norms, and predispositions?</li><li>Are the preferred communication channels credible and trustworthy?</li></ul></li></ul></li><li><ol start="6"><li>Accessibility:</li></ol><ul><li>Confirm the TA’s accessibility through credible and frequently used communication channels.</li><li>Questions to Ask: <ul><li>Are there trustworthy and effective channels to reach this TA (e.g., key communicators, social media)?</li><li>How frequently does this TA use or rely on these channels?</li></ul></li></ul></li><li><ol start="7"><li>Arguments and Recommended Psychological Actions:</li></ol><ul><li>Verify the alignment of arguments with vulnerabilities and check that they logically lead to SPO achievement.</li><li>Recommend psychological actions that align with the arguments and vulnerabilities.</li><li>Questions to Ask: <ul><li>Do the main and supporting arguments logically align with the TA vulnerabilities and conditions?</li><li>Do the proposed psychological actions have the potential to exploit vulnerabilities effectively?</li></ul></li></ul></li><li><ol start="8"><li>Refine Assessment Criteria:</li></ol><ul><li>Validate that the assessment criteria align with the Hierarchy of Psychological Effects Model (HPEM).</li><li>Ensure the criteria are specific, measurable, and tailored to the SPO.</li><li>Questions to Ask: <ul><li>Are the assessment criteria specific and measurable against the desired behavior?</li><li>Do the criteria directly measure progress toward achieving the SPO?</li></ul></li></ul></li></ul><h2 id="general-questions-across-all-sections" tabindex="-1">General Questions Across All Sections: <a class="header-anchor" href="#general-questions-across-all-sections" aria-label="Permalink to &quot;General Questions Across All Sections:&quot;">​</a></h2><ul><li><p><strong>Are all sources cited, and assumptions clearly labeled?</strong></p><ul><li>Numerically number each sourced piece of information within the TAAW.</li><li>In the footer of each page, provide an abbreviated list of all sources, numbered in correspondence with the above information.</li><li>Create a bibliography containing all sources.</li><li>Ensure that sources can be found again by a third party.</li></ul></li><li><p><strong>Is the information presented logical, consistent, and aligned with previous guidance?</strong></p></li><li><p><strong>Are portion markings in agreement with sourced information?</strong></p></li></ul><p>[Up] [Required]</p>',39)])])}const p=i(o,[["render",r]]);export{m as __pageData,p as default};
